@RestController
@RequestMapping("/api/v1")
public class HelloController {
    public record Greeting(String message, long timestamp) {}

    @GetMapping("/hello")
    public Greeting hello(@RequestParam(defaultValue = "Developer") String name) {
        return new Greeting("Hello, " + name + "!", System.currentTimeMillis());
    }
}

public record CreateProductRequest(
    @NotBlank(message = "Name is required") String name,
    @Positive(message = "Price must be > 0") double price
) {}

@PostMapping("/products")
@ResponseStatus(HttpStatus.CREATED)
public ProductResponse create(@Valid @RequestBody CreateProductRequest req) {
    return new ProductResponse(UUID.randomUUID(), req.name(), req.price());
}

def filter_items(items: list[dict], min_price: float) -> list[dict]:
    """Filter items with price >= min_price and active status."""
    return [
        item for item in items
        if item.get('active', True) and item.get('price', 0.0) >= min_price
    ]

