def filter_and_discount(items, min_price, discount_rate):
    out = []
    for item in items:
        if item.get('active', True) and item.get('price', 0) >= min_price:
            discounted = round(item['price'] * (1 - discount_rate), 2)
            new_item = dict(item)
            new_item['discounted_price'] = discounted
            out.append(new_item)
    return out

